-- ======================= DAS1110 (DI-26-01-S2) =======================

-- task DAS-S2-A1
INSERT INTO coding_tasks (course_id, code, difficulty, status, max_points, scoring_strategy, max_attempts, cpu_time_limit_ms, wall_time_limit_ms, memory_limit_kb, published_at)
SELECT (SELECT c.id FROM courses c JOIN subjects s ON s.id=c.subject_id WHERE s.code=$qn4$DAS1110$qn4$ AND c.cohort_code=$qn5$DI-26-01-S2$qn5$), $qn6$DAS-S2-A1$qn6$, $qn7$MEDIUM$qn7$, 'PUBLISHED', 100, 'PER_TEST_WEIGHTED', 20, 2000, 10000, 262144, now()
WHERE (SELECT c.id FROM courses c JOIN subjects s ON s.id=c.subject_id WHERE s.code=$qn4$DAS1110$qn4$ AND c.cohort_code=$qn5$DI-26-01-S2$qn5$) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM coding_tasks WHERE code=$qn8$DAS-S2-A1$qn8$);
INSERT INTO coding_task_translations (coding_task_id, locale, title, description, instructions, constraints_text)
SELECT id, 'uz', $qn9$Matritsa satrlarini saralash$qn9$, $qna$<p>n × m matritsaning har bir satrini oʻsish tartibida saralang.</p>$qna$, $qnb$Kirish: n m; soʻng n ta satrda m tadan butun son. Chiqish: saralangan matritsa, har satr bitta boʻsh joy bilan.$qnb$, $qnc$1 ≤ n, m ≤ 100.$qnc$
FROM coding_tasks WHERE code=$qnd$DAS-S2-A1$qnd$ ON CONFLICT DO NOTHING;
INSERT INTO coding_task_languages (coding_task_id, language_code, starter_code, solution_code)
SELECT id, $qne$python$qne$, $qnf$n, m = map(int, input().split())
rows = [list(map(int, input().split())) for _ in range(n)]
# TODO: har bir satrni saralang va chiqaring
$qnf$, $qng$n, m = map(int, input().split())
for _ in range(n):
    row = sorted(map(int, input().split()))
    print(" ".join(map(str, row)))
$qng$ FROM coding_tasks WHERE code=$qnh$DAS-S2-A1$qnh$
ON CONFLICT DO NOTHING;
INSERT INTO coding_task_languages (coding_task_id, language_code, starter_code, solution_code)
SELECT id, $qni$java$qni$, $qnj$import java.util.*;

public class Main {
    public static void main(String[] args) {
