$q12j$, $q12k$import java.util.*;

public class Main {
    static class BankAccount {
        private long balance = 0;

        void deposit(long amount) { balance += amount; }

        boolean withdraw(long amount) {
            if (amount > balance) return false;
            balance -= amount;
            return true;
        }

        long balance() { return balance; }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = Integer.parseInt(in.nextLine().trim());
        BankAccount acc = new BankAccount();
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String[] parts = in.nextLine().trim().split(" ");
            switch (parts[0]) {
                case "deposit" -> acc.deposit(Long.parseLong(parts[1]));
                case "withdraw" -> { if (!acc.withdraw(Long.parseLong(parts[1]))) out.append("Mablag yetarli emas\n"); }
                default -> out.append(acc.balance()).append('\n');
            }
        }
        System.out.print(out);
    }
}
