$q23a$, $q23b$import java.util.*;

public class Main {
    static String level(int s) {
        if (s <= 4) return "Past";
        if (s <= 9) return "O'rta";
        if (s <= 16) return "Yuqori";
        return "Kritik";
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        List<String> names = new ArrayList<>();
        List<Integer> scores = new ArrayList<>();
        for (int k = 0; k < n; k++) {
            names.add(in.next());
            scores.add(in.nextInt() * in.nextInt());
        }
        Integer[] order = new Integer[n];
        for (int k = 0; k < n; k++) order[k] = k;
        Arrays.sort(order, (a, b) -> scores.get(b) - scores.get(a)); // barqaror
        for (int k : order) System.out.println(names.get(k) + " " + scores.get(k) + " " + level(scores.get(k)));
    }
}
