$q294$, $q295$import java.util.*;

public class Main {
    static final Set<String> COMMON = Set.of("password", "123456", "12345678", "qwerty", "admin", "parol");

    static int score(String pw) {
        if (COMMON.contains(pw.toLowerCase())) return 0;
        boolean lower = false, upper = false, digit = false, special = false;
        for (char c : pw.toCharArray()) {
            if (Character.isLowerCase(c)) lower = true;
            else if (Character.isUpperCase(c)) upper = true;
            else if (Character.isDigit(c)) digit = true;
            else special = true;
        }
        int s = 0;
        for (boolean b : new boolean[] {pw.length() >= 8, pw.length() >= 12, lower, upper, digit, special}) if (b) s++;
        return s;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        for (int k = 0; k < n; k++) {
            int s = score(in.next());
            System.out.println(s + " " + (s <= 2 ? "Zaif" : s <= 4 ? "O'rtacha" : "Kuchli"));
        }
    }
}
