$q2a4$, $q2a5$import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        for (int k = 0; k < n; k++) {
            String s = in.next();
            StringBuilder digits = new StringBuilder();
            for (int g = 0; g < 3; g++) {
                int v = 0;
                for (char c : s.substring(1 + 3 * g, 4 + 3 * g).toCharArray())
                    v += c == 'r' ? 4 : c == 'w' ? 2 : c == 'x' ? 1 : 0;
                digits.append(v);
            }
            String kind = s.charAt(0) == 'd' ? "katalog" : s.charAt(0) == 'l' ? "havola" : "fayl";
            System.out.println(digits + " " + kind);
        }
    }
}
