    VALUES (v_lesson, v_pos, $q2n4$TEXT$q2n4$, true, ('' || chr(123) || $q2n3$}$q2n3$)::jsonb) RETURNING id INTO v_block;
    INSERT INTO content_block_translations (block_id, locale, payload, plain_text)
    VALUES (v_block, 'uz', ('' || chr(123) || $q2n5$"html":"<h2>Mavzu mazmuni</h2><p><strong>Kiberxavfsizlik</strong> — kompyuter tizimlari, tarmoqlar va maʼlumotlarni ruxsatsiz kirish, oʻzgartirish va yoʻq qilishdan himoyalash amaliyoti. Uning markazida uchta xossa turadi — <strong>CIA triadasi</strong>.</p><h3>Asosiy tushunchalar</h3><ul><li><strong>Konfidensiallik</strong> — maʼlumot faqat vakolatli shaxslarga ochiq.</li><li><strong>Yaxlitlik</strong> — maʼlumot ruxsatsiz oʻzgartirilmagan.</li><li><strong>Foydalanish mumkinligi</strong> — maʼlumot va xizmatlar kerak paytda ishlaydi.</li><li><strong>Tahdid</strong> — zarar yetkazishi mumkin boʻlgan hodisa yoki shaxs; <strong>zaiflik</strong> — tizimdagi kamchilik; <strong>risk</strong> — tahdid zaiflikdan foydalanish ehtimoli × oqibati.</li><li><strong>Nazorat vositalari</strong>: maʼmuriy (siyosat, oʻqitish), texnik (shifrlash, firewall), fizik (qulflar).</li></ul><table><thead><tr><th>Hodisa</th><th>Buzilgan xossa</th></tr></thead><tbody><tr><td>Maʼlumotlar bazasi sizib chiqdi</td><td>Konfidensiallik</td></tr><tr><td>Baho ruxsatsiz oʻzgartirildi</td><td>Yaxlitlik</td></tr><tr><td>Sayt DDoS hujumi tufayli ishlamayapti</td><td>Foydalanish mumkinligi</td></tr></tbody></table>"}$q2n5$)::jsonb, $q2n6$Mavzu mazmuni Kiberxavfsizlik — kompyuter tizimlari, tarmoqlar va maʼlumotlarni ruxsatsiz kirish, oʻzgartirish va yoʻq qilishdan himoyalash amaliyoti. Uning markazida uchta xossa turadi — CIA triadasi . Asosiy tushunchalar Konfidensiallik — maʼlumot faqat vakolatli shaxslarga ochiq. Yaxlitlik — maʼlumot ruxsatsiz oʻzgartirilmagan. Foydalanish mumkinligi — maʼlumot va xizmatlar kerak paytda ishlaydi. Tahdid — zarar yetkazishi mumkin boʻlgan hodisa yoki shaxs; zaiflik — tizimdagi kamchilik; risk — tahdid zaiflikdan foydalanish ehtimoli × oqibati. Nazorat vositalari : maʼmuriy (siyosat, oʻqitish), texnik (shifrlash, firewall), fizik (qulflar). Hodisa Buzilgan xossa Maʼlumotlar bazasi sizib chiqdi Konfidensiallik Baho ruxsatsiz oʻzgartirildi Yaxlitlik Sayt DDoS hujumi tufayli ishlamayapti Foydalanish mumkinligi$q2n6$);
    v_pos := v_pos + 1;
  END IF;
  IF true THEN
