    VALUES (v_lesson, v_pos, $q2n8$CALLOUT$q2n8$, true, ('' || chr(123) || $q2n7$"variant":"WARNING"}$q2n7$)::jsonb) RETURNING id INTO v_block;
    INSERT INTO content_block_translations (block_id, locale, payload, plain_text)
