        StringBuilder out = new StringBuilder();
        char level = '-';
        for (char b : bits.toCharArray()) {
            switch (scheme) {
                case "NRZ" -> out.append(b == '1' ? '+' : '-');
                case "NRZI" -> {
                    if (b == '1') level = level == '-' ? '+' : '-';
                    out.append(level);
                }
                default -> out.append(b == '1' ? "-+" : "+-");
            }
        }
        System.out.println(out);
    }
}
