        String line;
        while ((line = br.readLine()) != null && !line.isBlank()) {
            int colon = line.indexOf(':');
            headers.put(line.substring(0, colon).trim().toLowerCase(), line.substring(colon + 1).trim());
        }
        System.out.println("Metod: " + requestLine[0]);
        System.out.println("Yo'l: " + path);
        System.out.println("So'rov: " + query);
        System.out.println("Versiya: " + requestLine[2]);
        System.out.println("Host: " + headers.getOrDefault("host", "-"));
        System.out.println("Sarlavhalar: " + headers.size());
    }
}
