$q3h7$, $q3h8$import sys


def to_int(s):
    a, b, c, d = map(int, s.split("."))
    return (a << 24) | (b << 16) | (c << 8) | d


def in_cidr(addr, cidr):
    net, length = cidr.split("/")
    length = int(length)
    mask = (0xFFFFFFFF << (32 - length)) & 0xFFFFFFFF if length else 0
    return to_int(addr) & mask == to_int(net) & mask


data = sys.stdin.read().split()
n = int(data[0])
rules = [data[1 + 4 * i:5 + 4 * i] for i in range(n)]
pos = 1 + 4 * n
m = int(data[pos])
for k in range(m):
    proto, port, src = data[pos + 1 + 3 * k:pos + 4 + 3 * k]
    verdict = "DENY default"
    for i, (action, r_proto, r_port, r_src) in enumerate(rules, 1):
        if r_proto in ("any", proto) and r_port in ("*", port) and in_cidr(src, r_src):
            verdict = f"{action} {i}"
            break
    print(verdict)
