public class Main {
    static long ip(String s) {
        String[] p = s.split("\\.");
        long v = 0;
        for (String x : p) v = (v << 8) | Integer.parseInt(x);
        return v;
    }

    static String str(long v) {
        return ((v >> 24) & 255) + "." + ((v >> 16) & 255) + "." + ((v >> 8) & 255) + "." + (v & 255);
    }

    static long mask(int len) {
        return len == 0 ? 0 : (0xFFFFFFFFL << (32 - len)) & 0xFFFFFFFFL;
    }

    static boolean inCidr(String addr, String cidr) {
        String[] p = cidr.split("/");
        long m = mask(Integer.parseInt(p[1]));
        return (ip(addr) & m) == (ip(p[0]) & m);
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        String[][] rules = new String[n][];
        for (int i = 0; i < n; i++) rules[i] = new String[] {in.next(), in.next(), in.next(), in.next()};
        int m = in.nextInt();
        for (int k = 0; k < m; k++) {
            String proto = in.next(), port = in.next(), src = in.next();
            String verdict = "DENY default";
            for (int i = 0; i < n; i++) {
                String[] r = rules[i];
                if ((r[1].equals("any") || r[1].equals(proto)) && (r[2].equals("*") || r[2].equals(port)) && inCidr(src, r[3])) {
                    verdict = r[0] + " " + (i + 1);
                    break;
                }
            }
            System.out.println(verdict);
        }
    }
}
