  IF NOT EXISTS (SELECT 1 FROM content_blocks x WHERE x.lesson_id=v_lesson AND x.block_type=$q4q5$QUIZ_REF$q4q5$ AND x.settings->>'refId'=(jsonb_build_object('refId', (SELECT id FROM quizzes WHERE code=$q4q4$IAKTT-Q-S14$q4q4$)::text))->>'refId') AND (jsonb_build_object('refId', (SELECT id FROM quizzes WHERE code=$q4q4$IAKTT-Q-S14$q4q4$)::text))->>'refId' IS NOT NULL THEN
    INSERT INTO content_blocks (lesson_id, position, block_type, is_required, settings)
    VALUES (v_lesson, v_pos, $q4q6$QUIZ_REF$q4q6$, true, jsonb_build_object('refId', (SELECT id FROM quizzes WHERE code=$q4q4$IAKTT-Q-S14$q4q4$)::text)) RETURNING id INTO v_block;
